(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-111":{scenario:{company:"Ngọc Trúc Office Solutions",supervisor:{name:"Lê Thị Thu Hà",role:{vi:"Kế toán trưởng",en:"Chief Accountant"}},ref_code:"JV-2512",title:{vi:"Đúng kỳ, đúng tài khoản, đúng bản chất.",en:"Right period, right account, right substance."},brief:{vi:"Ngày 01/08/2025 công ty trả trước 432 triệu đồng (chưa gồm thuế GTGT) tiền thuê văn phòng 18 tháng, từ 01/08/2025 đến 31/01/2027. Bản nháp bút toán JV-2512 ghi toàn bộ vào chi phí quản lý doanh nghiệp năm 2025. Năm tài chính trùng năm dương lịch, công ty áp dụng Thông tư 200/2014/TT-BTC. Sửa tài khoản ghi Nợ khi trả tiền và chi phí thuê thuộc năm 2025, rồi lập báo cáo có căn cứ.",en:"On 1 Aug 2025 the company prepaid VND 432 million (excluding VAT) of office rent for 18 months, from 1 Aug 2025 to 31 Jan 2027. Draft journal JV-2512 books the full amount as 2025 administrative expense. The fiscal year is the calendar year and the company applies Circular 200/2014/TT-BTC. Correct the debit account at payment and the 2025 rent expense, then write an evidence-based report."},reference_title:{vi:"Hợp đồng thuê & lịch phân bổ đã duyệt · JV-2512",en:"Lease contract & approved allocation schedule · JV-2512"},fields:[{id:"INIT_ACCT",label:{vi:"Tài khoản ghi Nợ khi trả trước",en:"Debit account at prepayment"},initial:"642",expected:"242",choices:["642","242","335"],reference:"Hợp đồng thuê & chính sách kế toán",hint:{vi:"Khoản chi mang lại lợi ích cho nhiều kỳ chưa phải chi phí của kỳ trả tiền; TK 335 dành cho chi phí đã phát sinh nhưng chưa trả.",en:"A payment benefiting several periods is not yet an expense of the payment period; account 335 is for costs incurred but unpaid."}},{id:"RENT_2025",label:{vi:"Chi phí thuê ghi nhận năm 2025 (VND)",en:"2025 rent expense (VND)"},initial:"432000000",expected:"120000000",reference:"Lịch phân bổ chi phí trả trước",ref_value:{vi:"Tổng 432.000.000 đồng; 18 tháng từ 01/08/2025; ngày khóa sổ 31/12/2025",en:"Total VND 432,000,000; 18 months from 1 Aug 2025; closing date 31 Dec 2025"},hint:{vi:"Chi phí của mỗi kỳ tương ứng với số tháng văn phòng thực sự được sử dụng trong kỳ đó.",en:"Each period's expense matches the number of months the office was actually used in that period."}}],sop32:{vi:"Chi phí trả trước phân bổ đều theo tháng hưởng lợi: chi phí tháng = tổng tiền trả trước / số tháng thuê; chi phí năm = chi phí tháng x số tháng đã sử dụng trong năm (Nợ 642 / Có 242).",en:"Prepaid costs are allocated evenly over the benefit months: monthly cost = total prepayment / lease months; annual cost = monthly cost x months used in the year (Dr 642 / Cr 242)."},context:{label:"SỔ CÁI NHÁP / JV-2512",metrics:[{label:{vi:"Tiền thuê trả trước",en:"Prepaid rent"},value:"432,000,000 VND"},{label:{vi:"Thời hạn thuê",en:"Lease term"},value:"01/08/2025 - 31/01/2027"},{label:{vi:"Ngày khóa sổ",en:"Closing date"},value:"31/12/2025"}]},crisis:{vi:"Giám đốc nhắn: “Cứ ghi hết 432 triệu vào chi phí năm nay cho lợi nhuận thấp xuống, đỡ thuế TNDN. Đằng nào cũng là tiền thật đã chi, ai kiểm tra đâu mà lo.”",en:"The director messages you: “Just expense the whole 432 million this year so profit drops and we pay less corporate income tax. It is real money already spent, nobody will check.”"},options:{safe:{vi:"Phân bổ theo thời gian hưởng lợi qua TK 242, giải thích nguyên tắc dồn tích và phù hợp, báo kế toán trưởng bằng văn bản; mọi phương án tối ưu thuế phải hợp pháp và có tư vấn.",en:"Allocate over the benefit period through account 242, explain the accrual and matching principles and inform the chief accountant in writing; any tax planning must be lawful and advised."},shortcut:{vi:"Ghi hết vào chi phí năm 2025 theo ý giám đốc, nếu bị thanh tra thuế thì điều chỉnh sau.",en:"Expense everything in 2025 as the director wants and adjust later if the tax authority audits."},wait:{vi:"Giữ nguyên bút toán nháp và chờ kiểm toán cuối năm tự phát hiện, tự quyết định.",en:"Leave the draft entry as it is and wait for the year-end auditors to find and decide."}},questions:{vi:["Vì sao khoản tiền thuê phải ghi Nợ TK 242 thay vì TK 642? Trình bày cách bạn tính chi phí thuê năm 2025 từ hợp đồng.","Nếu ghi toàn bộ vào chi phí năm 2025, báo cáo tài chính và quyết toán thuế TNDN bị ảnh hưởng thế nào và rủi ro gì?"],en:["Why must the rent be debited to account 242 instead of 642? Show how you calculated the 2025 rent expense from the contract.","If the whole amount is expensed in 2025, how are the financial statements and the corporate income tax finalization affected, and what are the risks?"]},hints:{vi:["Đặt bút toán nháp cạnh hợp đồng thuê và đánh dấu thời hạn hưởng lợi của khoản chi.","Đếm số tháng sử dụng văn phòng trong năm 2025 trước khi áp công thức ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không ghi nhận chi phí sai kỳ để điều chỉnh lợi nhuận hay số thuế phải nộp."],en:["Place the draft entry next to the lease and mark the benefit period of the payment.","Count the months of office use in 2025 before applying the formula in SOP 3.2.","Re-read SOP 4.2: never book expenses in the wrong period to manage profit or tax payable."]}},learning:{summary:{vi:"Kế toán tổng hợp kiểm tra và hạch toán toàn bộ nghiệp vụ, thực hiện các bút toán cuối kỳ như phân bổ, trích trước, khấu hao, đánh giá tỷ giá và kết chuyển, đối chiếu sổ chi tiết với sổ cái rồi lập báo cáo tài chính. Đây là người giữ bức tranh tài chính đúng kỳ, đúng bản chất, làm đầu mối cho quyết toán thuế và kiểm toán. Nghề đòi hỏi nắm vững Luật Kế toán, chuẩn mực kế toán Việt Nam và chế độ kế toán doanh nghiệp.",en:"A general accountant reviews and records all transactions, runs period-end entries such as allocations, accruals, depreciation, FX revaluation and closing transfers, reconciles subledgers to the general ledger and prepares the financial statements. The role keeps the financial picture in the right period and true to substance and is the focal point for tax finalization and audits. It requires solid command of the Accounting Law, Vietnamese Accounting Standards and the enterprise accounting regime."},responsibilities:{vi:["Kiểm tra chứng từ, hạch toán và rà soát bút toán của các phần hành trước khi khóa sổ.","Thực hiện bút toán cuối kỳ: phân bổ chi phí trả trước, trích trước, khấu hao, đánh giá lại ngoại tệ.","Đối chiếu sổ chi tiết công nợ, kho, tài sản, ngân hàng với sổ cái và xử lý chênh lệch.","Lập bảng cân đối số phát sinh và báo cáo tài chính năm, giữa niên độ.","Hỗ trợ quyết toán thuế, cung cấp hồ sơ cho kiểm toán độc lập và thanh tra."],en:["Check documents, post entries and review sub-ledger postings before closing.","Run period-end entries: prepaid allocation, accruals, depreciation and FX revaluation.","Reconcile receivable, inventory, asset and bank subledgers with the ledger and clear differences.","Prepare the trial balance and annual and interim financial statements.","Support tax finalization and provide files to external auditors and inspectors."]},competencies:[{name:{vi:"Nguyên tắc kế toán",en:"Accounting principles"},desc:{vi:"Vận dụng cơ sở dồn tích, phù hợp, thận trọng và nhất quán để ghi nhận đúng kỳ, đúng bản chất.",en:"Apply accrual, matching, prudence and consistency to record items in the right period and substance."}},{name:{vi:"Khóa sổ cuối kỳ",en:"Period-end close"},desc:{vi:"Lập và theo dõi danh mục công việc khóa sổ, bút toán điều chỉnh và lịch phân bổ.",en:"Build and track the closing checklist, adjusting entries and allocation schedules."}},{name:{vi:"Đối chiếu số liệu",en:"Reconciliation"},desc:{vi:"Phát hiện và giải thích chênh lệch giữa sổ chi tiết, sổ cái, sao kê và biên bản đối chiếu.",en:"Find and explain gaps between subledgers, ledger, statements and confirmations."}},{name:{vi:"Lập báo cáo tài chính",en:"Financial reporting"},desc:{vi:"Trình bày bảng cân đối, kết quả kinh doanh, lưu chuyển tiền tệ và thuyết minh đúng chuẩn mực.",en:"Present the balance sheet, income statement, cash flow and notes in line with standards."}},{name:{vi:"Chính trực nghề nghiệp",en:"Professional integrity"},desc:{vi:"Không ghi sai kỳ để làm đẹp hay giảm lợi nhuận; báo cáo bằng văn bản khi bị yêu cầu làm sai.",en:"Never shift periods to inflate or cut profit; escalate in writing when asked to misstate."}}],knowledge:{vi:["Luật Kế toán số 88/2015/QH13 và Nghị định 174/2016/NĐ-CP quy định chi tiết.","Thông tư 200/2014/TT-BTC về chế độ kế toán doanh nghiệp và Thông tư 133/2016/TT-BTC cho doanh nghiệp nhỏ và vừa (cùng các văn bản sửa đổi, thay thế).","VAS 01 Chuẩn mực chung: cơ sở dồn tích, phù hợp, thận trọng, trọng yếu.","VAS 21 Trình bày báo cáo tài chính và VAS 24 Báo cáo lưu chuyển tiền tệ.","Nghị định 123/2020/NĐ-CP về hóa đơn, chứng từ và yêu cầu chứng từ hợp lệ."],en:["Accounting Law No. 88/2015/QH13 and Decree 174/2016/ND-CP detailing it.","Circular 200/2014/TT-BTC on the enterprise accounting regime and Circular 133/2016/TT-BTC for SMEs (with amending or replacing documents).","VAS 01 Framework: accrual basis, matching, prudence and materiality.","VAS 21 Presentation of financial statements and VAS 24 Cash flow statements.","Decree 123/2020/ND-CP on invoices and documents and what makes a document valid."]},tools:["Phần mềm kế toán doanh nghiệp (ERP)","Microsoft Excel","Hệ thống hóa đơn điện tử","Ngân hàng điện tử (sao kê)","Phần mềm hỗ trợ kê khai thuế"],kpis:{vi:["Số ngày khóa sổ tháng sau ngày cuối kỳ.","Số bút toán điều chỉnh do kiểm toán đề xuất (mục tiêu giảm dần).","Tỷ lệ tài khoản được đối chiếu và ký xác nhận hằng tháng.","Số lần nộp báo cáo, tờ khai trễ hạn (mục tiêu bằng 0)."],en:["Days to close the month after period end.","Audit-proposed adjusting entries (target decreasing).","Share of accounts reconciled and signed off monthly.","Late report or return filings (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra sao kê ngân hàng, đối chiếu thu chi phát sinh với sổ quỹ và sổ tiền gửi.",en:"Check bank statements and match receipts and payments with the cash and bank books."},{time:"09:30",vi:"Rà soát bút toán của kế toán công nợ, kho và tài sản; trả lại chứng từ thiếu căn cứ.",en:"Review postings from payables, inventory and assets; return poorly supported documents."},{time:"13:30",vi:"Cập nhật lịch phân bổ chi phí trả trước, trích trước chi phí lãi vay và điện nước.",en:"Update the prepaid allocation schedule and accrue interest and utility costs."},{time:"15:30",vi:"Đối chiếu sổ chi tiết với sổ cái, giải thích chênh lệch với kế toán trưởng.",en:"Reconcile subledgers to the ledger and explain differences to the chief accountant."},{time:"17:00",vi:"Lập bảng cân đối số phát sinh nháp và cập nhật danh mục công việc khóa sổ.",en:"Prepare a draft trial balance and update the closing checklist."}],mistakes:{vi:["Ghi thẳng khoản trả trước nhiều kỳ vào chi phí kỳ trả tiền, sai nguyên tắc phù hợp.","Quên trích trước chi phí đã phát sinh nhưng chưa có hóa đơn, làm lợi nhuận kỳ này cao giả tạo.","Khóa sổ khi sổ chi tiết chưa khớp sổ cái, để chênh lệch dồn sang kỳ sau."],en:["Expensing a multi-period prepayment in the payment period, breaching matching.","Failing to accrue costs incurred without an invoice yet, overstating current profit.","Closing while subledgers do not match the ledger, carrying differences forward."]},career:[{vi:"Kế toán viên phần hành",en:"Accounting clerk"},{vi:"Kế toán tổng hợp",en:"General accountant"},{vi:"Phó phòng / Kế toán trưởng",en:"Deputy / Chief accountant"},{vi:"Giám đốc tài chính (CFO)",en:"Chief Financial Officer (CFO)"}],glossary:[{term:"Chi phí trả trước",vi:"Khoản đã chi nhưng liên quan nhiều kỳ, được ghi vào TK 242 và phân bổ dần vào chi phí.",en:"Prepaid expense: paid amounts covering several periods, held in account 242 and allocated over time."},{term:"Chi phí phải trả",vi:"Chi phí đã phát sinh, đã nhận hàng hoặc dịch vụ nhưng chưa có hóa đơn hoặc chưa trả, ghi vào TK 335.",en:"Accrued expense: costs incurred for goods or services received but not yet invoiced or paid, in account 335."},{term:"Cơ sở dồn tích",vi:"Nghiệp vụ được ghi nhận khi phát sinh, không căn cứ vào thời điểm thu hoặc chi tiền.",en:"Accrual basis: transactions are recognized when they occur, not when cash moves."},{term:"Khóa sổ",vi:"Hoàn tất ghi chép, điều chỉnh, kết chuyển và chốt số liệu của một kỳ kế toán.",en:"Closing: completing entries, adjustments and transfers and locking a period's figures."},{term:"Bảng cân đối số phát sinh",vi:"Bảng tổng hợp số dư đầu kỳ, phát sinh và số dư cuối kỳ của mọi tài khoản để kiểm tra cân đối.",en:"Trial balance: a summary of opening balances, movements and closing balances of all accounts."}],quiz:[{q:{vi:"Công ty trả trước 240 triệu đồng tiền bảo hiểm tài sản 24 tháng từ 01/10. Chi phí ghi nhận đến 31/12 cùng năm là bao nhiêu?",en:"A company prepays VND 240 million of property insurance for 24 months from 1 October. What expense is recognized by 31 December of that year?"},options:{vi:["240 triệu đồng","120 triệu đồng","10 triệu đồng","30 triệu đồng"],en:["VND 240 million","VND 120 million","VND 10 million","VND 30 million"]},answer:3,explain:{vi:"Mỗi tháng 240 / 24 = 10 triệu đồng; từ tháng 10 đến tháng 12 là 3 tháng nên chi phí là 30 triệu đồng.",en:"Monthly cost is 240 / 24 = VND 10 million; October to December is 3 months, so VND 30 million."}},{q:{vi:"Điện tháng 12 đã sử dụng nhưng đầu tháng 1 mới có hóa đơn. Khi khóa sổ năm, kế toán ghi nhận thế nào?",en:"December electricity was used but the invoice arrives in early January. How is it handled at year-end close?"},options:{vi:["Không ghi gì, chờ hóa đơn","Trích trước vào chi phí tháng 12, ghi Có TK 335","Ghi vào chi phí trả trước TK 242","Ghi vào chi phí năm sau"],en:["Record nothing until the invoice","Accrue it in December, credit account 335","Record it as a prepaid expense in account 242","Expense it next year"]},answer:1,explain:{vi:"Theo cơ sở dồn tích, chi phí đã phát sinh phải ghi nhận đúng kỳ thông qua chi phí phải trả.",en:"Under the accrual basis, an incurred cost is recognized in its period through an accrued liability."}},{q:{vi:"Nguyên tắc nào yêu cầu ghi nhận chi phí tương ứng với doanh thu và lợi ích của cùng kỳ?",en:"Which principle requires expenses to be recognized with the revenue and benefits of the same period?"},options:{vi:["Giá gốc","Hoạt động liên tục","Phù hợp","Trọng yếu"],en:["Historical cost","Going concern","Matching","Materiality"]},answer:2,explain:{vi:"Nguyên tắc phù hợp trong VAS 01 gắn chi phí với doanh thu và kỳ mà chúng tạo ra lợi ích.",en:"The matching principle in VAS 01 links costs to the revenue and periods they benefit."}},{q:{vi:"Giám đốc yêu cầu dồn chi phí năm sau vào năm nay để giảm thuế TNDN. Bạn làm gì?",en:"The director asks you to pull next year's costs into this year to cut corporate income tax. What do you do?"},options:{vi:["Từ chối, giải thích nguyên tắc dồn tích và báo kế toán trưởng bằng văn bản","Làm theo vì giám đốc chịu trách nhiệm","Ghi một nửa cho cân bằng","Chờ kiểm toán phát hiện rồi sửa"],en:["Refuse, explain the accrual principle and inform the chief accountant in writing","Comply because the director is responsible","Book half as a compromise","Wait for the auditors to find it"]},answer:0,explain:{vi:"Ghi sai kỳ để giảm thuế là sai phạm kế toán và thuế; kế toán phải từ chối và lưu bằng chứng.",en:"Shifting periods to cut tax is an accounting and tax violation; refuse and keep evidence."}}],tools_en:["Enterprise accounting software (ERP)","Microsoft Excel","E-invoicing system","Online banking (bank statements)","Tax filing support software"]}}})})(window.KKR);
